(function(scope){'use strict';
const N=256,EPS=.00001;
class FloodNetwork{
 constructor({solve,base,onUpdate}){this.solve=solve;this.base=base;this.onUpdate=onUpdate;this.entries=new Map();this.jobs=0;this.waiters=[]}
 key(c){return c.z+'/'+c.x+'/'+c.y}
 neighbor(e,dx,dy){const total=2**e.coords.z,y=e.coords.y+dy;if(y<0||y>=total)return null;return this.entries.get(this.key({z:e.coords.z,x:(e.coords.x+dx+total)%total,y}))}
 attach(record,dem=record.dem){let e=this.entries.get(this.key(record.coords));if(!e){e={key:this.key(record.coords),coords:record.coords,dem,base:this.base({coords:record.coords,dem}),records:new Set(),threshold:null,sea:null,running:false,dirty:false,version:0,first:[]};this.entries.set(e.key,e)}e.records.add(record);record.networkEntry=e;if(e.threshold){this.assign(e,record);this.request(e);return Promise.resolve()}const result=new Promise((resolve,reject)=>e.first.push({resolve,reject}));this.request(e);return result}
 detach(record){const e=record.networkEntry;if(e)e.records.delete(record);this.trim()}
 assign(e,r){if(!r.live)return;r.dem=e.dem;r.threshold=e.threshold;r.sea=e.sea;r.gpuVersion=e.version;this.onUpdate(r)}
 parentCost(e,x,y,cost){for(let z=e.coords.z-1;z>=1;z--){const factor=2**(e.coords.z-z),p=this.entries.get(this.key({z,x:Math.floor(e.coords.x/factor),y:Math.floor(e.coords.y/factor)}));if(!p||!p.threshold)continue;const px=Math.min(255,Math.floor(((e.coords.x%factor)+(x+.5)/N)/factor*N)),py=Math.min(255,Math.floor(((e.coords.y%factor)+(y+.5)/N)/factor*N));cost=Math.min(cost,p.threshold[py*N+px])}return cost}
 boundary(e){const spill=e.base.slice(),left=this.neighbor(e,-1,0),right=this.neighbor(e,1,0),top=this.neighbor(e,0,-1),bottom=this.neighbor(e,0,1);for(let k=0;k<N;k++){const pairs=[[k*N,left,k*N+N-1],[k*N+N-1,right,k*N],[k,top,(N-1)*N+k],[(N-1)*N+k,bottom,k]];for(const [i,other,j] of pairs){let h=spill[i];if(e.threshold)h=Math.min(h,e.threshold[i]);if(other&&other.threshold)h=Math.min(h,other.threshold[j]);spill[i]=this.parentCost(e,i%N,i/N|0,h)}}return spill}
 request(e){if(e.running){e.dirty=true;return}e.running=true;this.jobs++;const spill=this.boundary(e);this.solve(e.dem,spill,e).then(result=>{let changed=!e.threshold;const previous=e.threshold;if(previous){for(let i=0;i<result.threshold.length;i++){result.threshold[i]=Math.min(previous[i],result.threshold[i]);result.sea[i]|=e.sea[i];if(result.threshold[i]<previous[i]-EPS)changed=true}}if(changed){e.threshold=result.threshold;e.sea=result.sea;e.version++;for(const r of e.records)this.assign(e,r);this.propagate(e)}for(const first of e.first)first.resolve();e.first=[]}).catch(error=>{for(const first of e.first)first.reject(error);e.first=[]}).finally(()=>{e.running=false;this.jobs--;if(e.dirty){e.dirty=false;this.request(e)}this.trim();if(this.jobs===0){for(const done of this.waiters)done();this.waiters=[]}})}
 propagate(e){for(const [dx,dy] of [[-1,0],[1,0],[0,-1],[0,1]]){const other=this.neighbor(e,dx,dy);if(!other)continue;let improves=!other.threshold;for(let k=0;k<N&&!improves;k++){const a=dx===-1?k*N:dx===1?k*N+N-1:dy===-1?k:(N-1)*N+k,b=dx===-1?k*N+N-1:dx===1?k*N:dy===-1?(N-1)*N+k:k;if(Math.max(e.threshold[a],other.dem[b],0)<other.threshold[b]-EPS)improves=true}if(improves)this.request(other)}for(const child of this.entries.values()){const d=child.coords.z-e.coords.z;if(d<=0||d>4||!child.threshold)continue;const factor=2**d;if(Math.floor(child.coords.x/factor)!==e.coords.x||Math.floor(child.coords.y/factor)!==e.coords.y)continue;const border=this.boundary(child);for(let k=0;k<N;k++){if([k,(N-1)*N+k,k*N,k*N+N-1].some(i=>Math.max(0,border[i],child.dem[i])<child.threshold[i]-EPS)){this.request(child);break}}}}
 trim(){if(this.entries.size<=96)return;for(const [key,e] of this.entries){if(this.entries.size<=96)break;if(!e.running&&!e.records.size)this.entries.delete(key)}}
 settled(){return this.jobs===0?Promise.resolve():new Promise(resolve=>this.waiters.push(resolve))}
}
scope.DeepTerraFloodNetwork=FloodNetwork;
})(typeof self!=='undefined'?self:globalThis);
